INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Normalisierung immer notwendig für eine Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Anforderungen ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Normalisierung?', 3, '[{"text": "Redundanz vermeiden", "correct": true, "because": "Spart Speicher und Fehler"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Sekundär"}, {"text": "Einfache Struktur", "correct": false, "because": "Kann komplexer werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ziele verfolgt die Normalisierung?', 5, '[{"text": "Datenredundanz reduzieren", "correct": true, "because": "Vermeidet Inkonsistenzen"}, {"text": "Integrität sichern", "correct": true, "because": "Schützt Datenkonsistenz"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Tabellen", "correct": false, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Normalisierung teilt Tabellen. b) Sie erhöht immer die Performance.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance kann leiden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Normalisierung?', 4, '[{"text": "Funktionale Abhängigkeiten", "correct": false, "because": "Kern der Normalisierung"}, {"text": "Schlüsseldefinition", "correct": false, "because": "Sichert Struktur"}, {"text": "Tabellenfarben", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Normalisierung die Abfragezeit verkürzt?', 2, '[{"text": "Nein", "correct": true, "because": "Kann durch Joins länger dauern"}, {"text": "Ja", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalform wähle ich, um Redundanz zu minimieren?', 3, '[{"text": "3NF", "correct": true, "because": "Eliminiert transitive Abhängigkeiten"}, {"text": "1NF", "correct": false, "because": "Nur atomare Werte"}, {"text": "4NF", "correct": false, "because": "Spezialisierter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt mir die Normalisierung?', 5, '[{"text": "Weniger Datenanomalien", "correct": true, "because": "Konsistenz gewährleistet"}, {"text": "Kleinere Tabellen", "correct": true, "because": "Redundanz reduziert"}, {"text": "Schnellere Joins", "correct": false, "because": "Kann komplexer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Normalisierung reduziert Redundanz. b) Sie macht Abfragen immer schneller. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Normalisierung?', 4, '[{"text": "Primärschlüssel", "correct": false, "because": "Sichert Eindeutigkeit"}, {"text": "Funktionale Abhängigkeiten", "correct": false, "because": "Grundlage"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die 1NF schon ausreichend für alle Datenbanken?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Basisanforderungen"}, {"text": "Ja", "correct": false, "because": "Höhere Formen oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Normalisierung effektiv?', 4, '[{"text": "Korrekte Schlüssel", "correct": true, "because": "Sichern Integrität"}, {"text": "Abhängigkeitsanalyse", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Normalisierung nur für große Datenbanken ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine profitieren"}, {"text": "Ja", "correct": false, "because": "Größe egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Normalisierung unwichtig?', 3, '[{"text": "Tabellenaufteilung", "correct": false, "because": "Kernprozess"}, {"text": "Schlüsseldefinition", "correct": false, "because": "Sichert Struktur"}, {"text": "Design der GUI", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Normalisierung verhindert Anomalien. b) Sie braucht keine Schlüssel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schlüssel essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalform löst transitive Abhängigkeiten?', 5, '[{"text": "3NF", "correct": true, "because": "Entfernt transitive Abhängigkeiten"}, {"text": "2NF", "correct": false, "because": "Nur partielle Abhängigkeiten"}, {"text": "BCNF", "correct": false, "because": "Strenger als 3NF"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Anomalien beim Löschen zu vermeiden?', 4, '[{"text": "Normalisierung in 3NF", "correct": true, "because": "Integrität gewährleistet"}, {"text": "Daten duplizieren", "correct": false, "because": "Erhöht Anomalien"}, {"text": "Keine Schlüssel", "correct": false, "because": "Verschlechtert Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Normalisierung die Datenmenge erhöhen?', 3, '[{"text": "Ja", "correct": true, "because": "Durch Tabellenaufteilung"}, {"text": "Nein", "correct": false, "because": "Kann mehr Tabellen erzeugen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Normalisierung immer bis 5NF geht?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Anforderungen ab"}, {"text": "Ja", "correct": false, "because": "Oft 3NF ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft mir bei der Normalisierung?', 4, '[{"text": "Funktionale Abhängigkeit", "correct": true, "because": "Basis für Aufteilung"}, {"text": "Schnelle Joins", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Systematik zählt"}]');
